<?php
namespace PharmaSure\Integrations\Rest;
use PharmaSure\Core\TenantContext;use PharmaSure\Integrations\Services\IntegrationService;use PharmaSure\Integrations\Services\CallbackService;
final class IntegrationController{public static function register_routes(){$s=new self();register_rest_route('pharmasure/v1','/integrations',array('methods'=>\WP_REST_Server::CREATABLE,'callback'=>array($s,'configure'),'permission_callback'=>array($s,'can_manage')));register_rest_route('pharmasure/v1','/integrations/(?P<id>\d+)/deliveries',array('methods'=>\WP_REST_Server::CREATABLE,'callback'=>array($s,'enqueue'),'permission_callback'=>array($s,'can_use')));register_rest_route('pharmasure/v1','/integrations/callbacks/(?P<tenant>\d+)/(?P<config>\d+)',array('methods'=>\WP_REST_Server::CREATABLE,'callback'=>array($s,'callback'),'permission_callback'=>'__return_true'));}
	public function can_manage(){return current_user_can('pharmasure_manage_integrations')?true:new \WP_Error('forbidden','Integration management permission is required.',array('status'=>403));}public function can_use(){return current_user_can('pharmasure_use_integrations')?true:new \WP_Error('forbidden','Integration use permission is required.',array('status'=>403));}
	public function configure($r){$scope=$this->scope($r);return is_wp_error($scope)?$scope:$this->respond((new IntegrationService())->configure($scope['tenant_id'],$scope['branch_id'],(array)$r->get_json_params(),get_current_user_id()),201);}public function enqueue($r){$scope=$this->scope($r);$b=(array)$r->get_json_params();return is_wp_error($scope)?$scope:$this->respond((new IntegrationService())->enqueue($scope['tenant_id'],absint($r['id']),$b['event_type']??'',(array)($b['payload']??array()),$b['idempotency_key']??''),202);}public function callback($r){$body=$r->get_body();return $this->respond((new CallbackService())->receive(absint($r['tenant']),absint($r['config']),$r->get_header('X-Provider-Event-Id'),$r->get_header('X-Provider-Event-Type'),$body,$r->get_header('X-PharmaSure-Timestamp'),$r->get_header('X-PharmaSure-Signature')),200);}
	private function scope($r){$c=TenantContext::instance();$tenant=(int)$c->get_tenant_id();if(!$tenant){return new \WP_Error('tenant_required','No tenant context is active.',array('status'=>403));}$branch=absint($r->get_header('X-PharmaSure-Branch'));if($branch&&!$c->can_access_branch($branch)){return new \WP_Error('branch_forbidden','Branch is not authorized.',array('status'=>403));}return array('tenant_id'=>$tenant,'branch_id'=>$branch);}private function respond($v,$status){return is_wp_error($v)?$v:new \WP_REST_Response(array('success'=>true,'data'=>$v),$status);}}
